\label{tra:duality:weighted}\label{tra:duality:weighted-statement}
There are absolute constants $L,C_0>0$ such that the following holds. Put $m=\sqrt n$, assume $m/2\le A,D\le2m$, and take $m$ sufficiently large that $\theta=1-L/\log m>0$. For all nonnegative functions $w_i:S_D\to[0,\infty)$ and $v_k:S_A\to[0,\infty)$,
\begin{equation}\label{tra:duality:eq5}
 \frac{n!}{|R||C|}\,
 \mathbb E_U\!\left[\mathbf1_{\mathcal I}
       \prod_{i=1}^A w_i(r_i)\prod_{k=1}^D v_k(c_k)\right]
 \le e^{C_0n^{.54}}
       \prod_{i=1}^A(\mathbb E w_i^{1/\theta})^\theta
       \prod_{k=1}^D(\mathbb E v_k^{1/\theta})^\theta .
\end{equation}
The expectations on the right are uniform on the indicated symmetric groups, and logarithms are natural.

\label{l:main}
Partition $X$ into $b$ nonempty sets $M_1,\ldots,M_b$. Put $H_i=H_{M_i}$. Suppose $f$ is a nonnegative measure on $G$ of mass at most one and, for every $g\in G$ and $i$,
\begin{equation}\label{l:main-cap}
 f(gH_i)\le \frac{B}{[G:H_i]}.
\end{equation}
For every $u>0$ and every irreducible $\rho$ of degree $D$,
\begin{equation}\label{l:main-hs}
 \|\widehat f(\rho)\|_{\HS}^2
 \le bBC_uD^{-1+(u+2)/b}.
\end{equation}
There is also an independent orbit-span proof of the bound
\begin{equation}\label{l:main-orbit}
 \|\widehat f(\rho)\|_{\op}^2
 \le bBC_uD^{-1+(u+2)/b}.
\end{equation}
No restriction is imposed on block sizes or on the multiplicities in $\rho|_{H_1\times\cdots\times H_b}$.

\label{l:degree-all-powers}
For every fixed real $u>0$,
\begin{equation}\label{l:degree-all-powers-equation}
 C_u:=\sup_{n\ge1}\sum_{\lambda\vdash n}D_\lambda^{-u}<\infty,
 \qquad Z_u(n)\longrightarrow0.
\end{equation}
Moreover there are absolute constants $c_1,c_2>0$ such that, for all
sufficiently large $n$ and every $\lambda\vdash n$,
\begin{equation}\label{l:degree-tail-exponential}
 D_\lambda\ge c_1e^{c_2k(\lambda)}.
\end{equation}
For each fixed positive $k$, these dimensions tend uniformly to infinity
among shapes with $k(\lambda)=k$.

\label{prop:orbit-lift}
Let \(n\) be a positive multiple of eight, and partition the labels of \(G=S_n\) into sets \(M_1,\ldots,M_8\) of size \(n/8\). For each \(a\), let \(H_a\) be the subgroup fixing every label outside \(M_a\). Suppose a probability measure \(\nu\) on \(G\) satisfies
\[
 \nu(gH_a)\le4\frac{|H_a|}{|G|}
 \qquad(g\in G,\ 1\le a\le8).
\]
Then every irreducible unitary representation \(\rho\) of \(G\), of degree \(D\), satisfies
\begin{equation}\label{eq:h-12}
 \|\widehat\nu(\rho)\|_{\mathrm{op}}
 \le A D^{-5/16},\qquad A=\sqrt{32C_1}.
\end{equation}

\label{ten:lowplanes:main}
There is an absolute $P\ge2$ such that for every dyadic $n\ge2$,
\begin{equation}\label{ten:lowplanes:eq:1}
 \operatorname{Tr}_{\rm reg}|Q_n|^P\le1+n^{-10}.
\end{equation}
If $v$ is an integer with $2v\ge P$, then $v$ independent sweeps have total-variation distance at most $\frac12n^{-5}$ from uniform, from every deterministic initial deck. Here $\|\mu-\nu\|_{\rm TV}=\tfrac12\sum_g|\mu(g)-\nu(g)|$.

\label{net:hightail}
There are absolute $b,\delta>0$ and an integer $J_0\ge1$ such that, uniformly in the tracked input injection of size $r$ and for every integer $J\ge J_0$,
\begin{align}
 \log_2\E 2^{b\sum_{j\ge J}C_j}&\le O(r2^{-bJ}),\label{net:highmgf}\\
 \log_2\E 2^{b\sum_jC_j}&\le O(r(r/n)^\delta).\label{net:sparsemgf}
\end{align}
The first bound also holds with expectation conditional on all input-side
switches and all output switches of heights at most $s$, for every integer
$0\le s\le d$ with $2s<J$, uniformly in the fixed switch values and with
the same absolute implied constant.

\label{n:strong-density}
There are absolute constants $p\in(1,2]$ and $C<\infty$ such that,
for every $N=2^d$, every coordinate order, every $0\le l\le N$,
either choice of $H_N$, and every $x\in\mathcal X_{N,l}$,
\begin{equation}\label{n:strong-injection-density}
 \frac1{(N)_l}\sum_{y\in\mathcal X_{N,l}}
       \big((N)_lH_N(x,y)\big)^p\le e^{Cl}.
\end{equation}
After increasing $C$, the same constants give
\begin{equation}\label{n:strong-density-power-normalization}
 N^{-l}\sum_{y\in\{0,1\}^{dl}}
       \big(N^lH_N(x,y)\big)^p\le e^{Cl},
\end{equation}
where the kernel is extended by zero on tuples with repeated positions.
Both conclusions hold with rows replaced by columns.

\label{n:strong-smoothing}
There are an absolute integer $u\ge1$ and an absolute $C<\infty$
such that, for every $N=2^d$, every coordinate order, every
$0\le l\le N$, every $x,y\in\mathcal X_{N,l}$, and either
$H_N=T_N^*T_N$ or $H_N=T_NT_N^*$,
\begin{equation}\label{n:strong-smoothing-eq}
 H_N^u(x,y)\le\frac{e^{Cl}}{(N)_l}.
\end{equation}
In particular, with unnormalized regular trace on $S_N$,
\begin{equation}\label{n:strong-regular-smoothing}
 \operatorname{Tr}_{\mathrm{reg}}|T_N|^{2u}\le e^{CN}.
\end{equation}

\label{n:coherent-contact}
There is an absolute constant $C_*>0$ such that for every dyadic
$n=2^d\ge2$, every $1\le k<n$, and every partition
$\lambda=(n-k,\beta)\vdash n$,
\begin{equation}\label{n:coherent-contact-sharp}
 \|T_n(\lambda)\|_{\op}^2
 \le \min\left\{1,\left(\frac{C_*dk}{n}\right)^{k/2}\right\}.
\end{equation}
For $k=1$ this operator is zero.  In particular, with an absolute
constant $C$ independent of $n,k,\lambda$,
\begin{equation}\label{rec:coherent-contact-bound}
 \|T_n(\lambda)\|_{\op}^2
 \le C^k(1+d)^{Ck}(k/n)^{k/2}.
\end{equation}
The same statements hold with the coordinate order reversed.

\label{rec:main-harmonic-cycle}
There are absolute constants $c,C,\zeta>0$, a number $\delta\in(0,1)$,
and an integer $p_0$ with the following properties.  For every dyadic $n$
and $\lambda=(n-k,\beta)\vdash n$ with $k\ge1$,
\begin{align}
 W_n(\lambda)&\le e^{-c\Lambda_n(k)},\label{rec:level-contraction}\\
 W_n(\lambda)&\le e^{C\Lambda_n(k)}f_\beta^{-\zeta}.
 \label{rec:tail-contraction}
\end{align}
Independently, for every $1\le k\le n$, let $X_{n,k}$ be the ordered injective $k$-tuples of positions, with
uniform probability measure, and let
$\mathcal K_{n,k}(x,y)=(n)_k\Pr_{K_n}(x\mapsto y)$ be its kernel density.
Then
\begin{align}
 \sup_x\E_y\mathcal K_{n,k}(x,y)^{1+\delta}
   &\le e^{C\Lambda_n(k)},\label{rec:tuple-moment}\\
 \operatorname{tr}_{X_{n,k}}K_n^{p_0}
   &\le e^{C\Lambda_n(k)}.\label{rec:tuple-flat-trace}
\end{align}
Consequently, after changing absolute constants,
\begin{align}
 \|T_n|_{V_\lambda}\|_{\op}
   &\le \exp[-c\{\Lambda_n(k)+\log f_\beta\}],
       \label{rec:combined-tail-norm}\\
 W_n(\lambda)&\le e^{-c_1\Lambda_n(k)}D_\lambda^{-c_2}
       \label{rec:combined-dimension-norm}
\end{align}
for absolute $c_1,c_2>0$.

\label{rec:adaptive-main}
There are absolute positive constants $c,c',C$ such that for every
dyadic $n$ and every partition $\lambda=(n-r,\rho)\vdash n$,
\begin{align}
 \|F_n|_{V_\lambda}\|_{\op}&\le e^{-c h_n(r)},
       \label{rec:generator-level-main}\\
 \Tr_{V_\lambda}F_n^4&\le
       \exp\{-c'\log D_\lambda+C h_n(r)\}.
       \label{rec:adaptive-trace-main}
\end{align}
Consequently $\|T_n|_{V_\lambda}\|_{\op}$ is at most
$\exp[-c_0\{\log D_\lambda+h_n(r)\}]$ for an absolute $c_0>0$.

\label{thm:weighted}
There are positive weights $W_\lambda$, an absolute finite $p_*$, and real
exponents $2\le p_d\le p_*$ such that, for every $d\ge1$ and every
$\lambda\vdash2^d$,
\begin{equation}\label{eq:weighted-main}
 D_\lambda^{3/4}\le W_\lambda\le D_\lambda,
 \qquad W_\lambda\|K_d(\lambda)\|_{p_d}^{p_d}\le1.
\end{equation}
Consequently $\|K_d(\lambda)\|_{\rm op}\le D_\lambda^{-3/(4p_*)}$.

\label{thm:occupied}
Take a grid with \(m\) rows and \(n\) columns, \(mn=N\), and consider any subset of \(s=N-t\) cells, with the group \(G_s\) on those cells. Let \(a\vdash s\) lie in the \(h,h\)-hook, \(1\le h\le N\). Decompose \(V_a\) under the within-row permutation subgroup of \(G_s\), and also (separately) the within-column subgroup. For types \(\sigma,\theta\) of these two groups, let \(I_{\sigma,u}: V_\sigma\to V_a\), \(I_{\theta,v}: V_\theta\to V_a\) be isometric embeddings giving orthogonal copies and spanning the respective isotypic spaces. Then
\begin{equation}
 \sum_{u,v}\|I_{\sigma,u}^* I_{\theta,v}\|_\infty^2
 \ \le\
 \exp\{C[(m+n+1)h^2\log(N+2)+t]\}\ \min\left\{1,\frac{D_\sigma D_\theta}{D_a}\right\}.       \label{ten:weighted:eq:7}
\end{equation}
Here \(\sigma\) and \(\theta\) can each consist of a tuple of partitions, and the infinity norm is the operator norm. For \(s=0\) the empty representation has dimension one.
